-- Places you will love: managed in the admin panel. Seeded with Wikimedia Commons photos (credit kept per photo).

CREATE TABLE places (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    slug        TEXT NOT NULL UNIQUE,
    name        TEXT NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    sort_order  INT  NOT NULL DEFAULT 0,
    active      BOOLEAN NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE place_photos (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    place_id   UUID NOT NULL REFERENCES places(id) ON DELETE CASCADE,
    url        TEXT NOT NULL,
    caption    TEXT,
    credit     TEXT,   -- e.g. "Ingo Mehling, CC BY-SA 4.0"; empty for photos you took or uploaded yourself
    source_url TEXT,   -- link to the original (licence requires it for Commons photos)
    sort_order INT NOT NULL DEFAULT 0
);
CREATE INDEX place_photos_place_idx ON place_photos(place_id, sort_order);

